import{_ as t,a,c as s,ac as o}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"第一册：英语初阶 · 单元 3 复习与自测 · 第63–69课","description":"L49–L72 原创练习和答案解析。","frontmatter":{"title":"第一册：英语初阶 · 单元 3 复习与自测 · 第63–69课","description":"L49–L72 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-1/unit-03/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 单元 3 复习与自测","summary":"L49–L72 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 单元 3 复习与自测 · 第56–62课","link":"/life/english/new-concept/book-1/unit-03/review-part-02"},"next":{"text":"第一册：英语初阶 · 单元 3 复习与自测 · 第70–72课","link":"/life/english/new-concept/book-1/unit-03/review-part-04"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 单元 3 复习与自测 · 第56–62课","link":"/life/english/new-concept/book-1/unit-03/review-part-02"},"next":{"text":"第一册：英语初阶 · 单元 3 复习与自测 · 第70–72课","link":"/life/english/new-concept/book-1/unit-03/review-part-04"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-03/review-part-03.md","filePath":"life/english/new-concept/book-1/unit-03/review-part-03.md"}'),n={name:"life/english/new-concept/book-1/unit-03/review-part-03.md"};function r(i,e,l,h,p,u){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="第一册-英语初阶-·-单元-3-复习与自测-·-第63–69课" tabindex="-1">第一册：英语初阶 · 单元 3 复习与自测 · 第63–69课 <a class="header-anchor" href="#第一册-英语初阶-·-单元-3-复习与自测-·-第63–69课" aria-label="Permalink to &quot;第一册：英语初阶 · 单元 3 复习与自测 · 第63–69课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/unit-03/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/unit-03/overview">单元导读</a> · <a href="/life/english/new-concept/book-1/unit-03/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-1/unit-03/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-1/unit-03/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-63-·-must-not-与-do-not-have-to" tabindex="-1">Lesson 63 · must not 与 do not have to <a class="header-anchor" href="#lesson-63-·-must-not-与-do-not-have-to" aria-label="Permalink to &quot;Lesson 63 · must not 与 do not have to {#lesson-63-·-must-not-与-do-not-have-to}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> You must not make noise in this room.</p><h3 id="练习-1-14" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-14" aria-label="Permalink to &quot;练习 1 {#练习-1-14}&quot;">​</a></h3><p>表达禁止：You ___ not enter.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> must</p><p><strong>解析：</strong> 按本课规则判断：must not 表示禁止，don&#39;t have to 或 needn&#39;t 表示不必，两者意义不同。You mustn&#39;t enter 是不得进入；You don&#39;t have to enter 是可以不进入。祈使句 Don&#39;t ... 也用于禁令。mustn&#39;t 后跟动词原形。理解规定时先判断是禁止某动作，还是免除义务，不能只因都有 not 就视为同义。</p></details><p><strong>表达迁移：</strong> 围绕“区分禁止和没有必要”写两至三句，再读给同伴听。至少使用一次must not 与 do not have to，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>You must not make noise in this room. You do not have to wait outside.</p><p>Must not 表禁止，make 用原形；noise 常作不可数名词，in this room 限定规则适用的地方。 Do not have to 表示没有义务，并非禁止；wait 用原形，outside 为地点副词。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-063">回看本课</a></p><h2 id="lesson-64-·-must-not-与-do-not-have-to" tabindex="-1">Lesson 64 · must not 与 do not have to <a class="header-anchor" href="#lesson-64-·-must-not-与-do-not-have-to" aria-label="Permalink to &quot;Lesson 64 · must not 与 do not have to {#lesson-64-·-must-not-与-do-not-have-to}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> You do not have to wait outside.</p><h3 id="练习-1-15" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-15" aria-label="Permalink to &quot;练习 1 {#练习-1-15}&quot;">​</a></h3><p>把“你不必等待”译成英语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> You do not have to wait.</p><p><strong>解析：</strong> 按本课规则判断：must not 表示禁止，don&#39;t have to 或 needn&#39;t 表示不必，两者意义不同。You mustn&#39;t enter 是不得进入；You don&#39;t have to enter 是可以不进入。祈使句 Don&#39;t ... 也用于禁令。mustn&#39;t 后跟动词原形。理解规定时先判断是禁止某动作，还是免除义务，不能只因都有 not 就视为同义。</p></details><p><strong>表达迁移：</strong> 围绕“区分禁止和没有必要”写两至三句，再读给同伴听。至少使用一次must not 与 do not have to，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>You do not have to wait outside. You must not make noise in this room.</p><p>Do not have to 表示没有义务，并非禁止；wait 用原形，outside 为地点副词。 Must not 表禁止，make 用原形；noise 常作不可数名词，in this room 限定规则适用的地方。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-064">回看本课</a></p><h2 id="lesson-65-·-时间表达与-can-表许可" tabindex="-1">Lesson 65 · 时间表达与 can 表许可 <a class="header-anchor" href="#lesson-65-·-时间表达与-can-表许可" aria-label="Permalink to &quot;Lesson 65 · 时间表达与 can 表许可 {#lesson-65-·-时间表达与-can-表许可}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Can I stay until a quarter past nine?</p><h3 id="练习-1-16" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-16" aria-label="Permalink to &quot;练习 1 {#练习-1-16}&quot;">​</a></h3><p>把 a quarter past nine 写为数字时间。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 9:15</p><p><strong>解析：</strong> 按本课规则判断：can 可表示许可，能否这样做需由语境区分能力和允许。询问许可 Can I ...?；答应或拒绝时注意语气。时间表达 half past eight 是八点半，a quarter to nine 是差一刻九点，即八点四十五。at 用在具体钟点前。must be home 强调要求，be home 不是动作 go home。</p></details><p><strong>表达迁移：</strong> 围绕“商量回家时间与表达许可”写两至三句，再读给同伴听。至少使用一次时间表达与 can 表许可，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Can I stay until a quarter past nine? You must be home by half past ten.</p><p>Can I 开头询问许可；stay 为原形，until a quarter past nine 表一直待到9:15。 Must 后接 be 原形；home 表在家，by half past ten 意为最迟10:30，不是必须恰好10:30。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-065">回看本课</a></p><h2 id="lesson-66-·-时间表达与-can-表许可" tabindex="-1">Lesson 66 · 时间表达与 can 表许可 <a class="header-anchor" href="#lesson-66-·-时间表达与-can-表许可" aria-label="Permalink to &quot;Lesson 66 · 时间表达与 can 表许可 {#lesson-66-·-时间表达与-can-表许可}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> You must be home by half past ten.</p><h3 id="练习-1-17" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-17" aria-label="Permalink to &quot;练习 1 {#练习-1-17}&quot;">​</a></h3><p>把 half past ten 写为数字时间。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 10:30</p><p><strong>解析：</strong> 按本课规则判断：can 可表示许可，能否这样做需由语境区分能力和允许。询问许可 Can I ...?；答应或拒绝时注意语气。时间表达 half past eight 是八点半，a quarter to nine 是差一刻九点，即八点四十五。at 用在具体钟点前。must be home 强调要求，be home 不是动作 go home。</p></details><p><strong>表达迁移：</strong> 围绕“商量回家时间与表达许可”写两至三句，再读给同伴听。至少使用一次时间表达与 can 表许可，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>You must be home by half past ten. Can I stay until a quarter past nine?</p><p>Must 后接 be 原形；home 表在家，by half past ten 意为最迟10:30，不是必须恰好10:30。 Can I 开头询问许可；stay 为原形，until a quarter past nine 表一直待到9:15。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-066">回看本课</a></p><h2 id="lesson-67-·-be-的过去式-was-were" tabindex="-1">Lesson 67 · be 的过去式 was/were <a class="header-anchor" href="#lesson-67-·-be-的过去式-was-were" aria-label="Permalink to &quot;Lesson 67 · be 的过去式 was/were {#lesson-67-·-be-的过去式-was-were}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I was at the library last Saturday.</p><h3 id="练习-1-18" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-18" aria-label="Permalink to &quot;练习 1 {#练习-1-18}&quot;">​</a></h3><p>填过去式：I ___ at the library last Saturday.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> was</p><p><strong>解析：</strong> 按本课规则判断：过去某时的身份、状态或位置可用 was/were。I/he/she/it 用 was，you/we/they 用 were。否定在后面加 not；疑问把 was/were 移到主语前。last weekend、yesterday 指已结束的过去。不要给含 was/were 的问句再加 did；也不要把现在的 are 原样用于过去。</p></details><p><strong>表达迁移：</strong> 围绕“回忆周末在哪里以及当时状态”写两至三句，再读给同伴听。至少使用一次be 的过去式 was/were，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I was at the library last Saturday. Were your friends at the concert yesterday?</p><p>I 配过去式 was；at the library 表位置，last Saturday 明确已结束的过去，前面不加 on。 Were 前置构成过去的 be 问句；your friends 为复数，at the concert 表地点或参与场景。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-067">回看本课</a></p><h2 id="lesson-68-·-be-的过去式-was-were" tabindex="-1">Lesson 68 · be 的过去式 was/were <a class="header-anchor" href="#lesson-68-·-be-的过去式-was-were" aria-label="Permalink to &quot;Lesson 68 · be 的过去式 was/were {#lesson-68-·-be-的过去式-was-were}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Were your friends at the concert yesterday?</p><h3 id="练习-1-19" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-19" aria-label="Permalink to &quot;练习 1 {#练习-1-19}&quot;">​</a></h3><p>填过去式：___ your friends at the concert?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Were</p><p><strong>解析：</strong> 按本课规则判断：过去某时的身份、状态或位置可用 was/were。I/he/she/it 用 was，you/we/they 用 were。否定在后面加 not；疑问把 was/were 移到主语前。last weekend、yesterday 指已结束的过去。不要给含 was/were 的问句再加 did；也不要把现在的 are 原样用于过去。</p></details><p><strong>表达迁移：</strong> 围绕“回忆周末在哪里以及当时状态”写两至三句，再读给同伴听。至少使用一次be 的过去式 was/were，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Were your friends at the concert yesterday? I was at the library last Saturday.</p><p>Were 前置构成过去的 be 问句；your friends 为复数，at the concert 表地点或参与场景。 I 配过去式 was；at the library 表位置，last Saturday 明确已结束的过去，前面不加 on。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-068">回看本课</a></p><h2 id="lesson-69-·-过去存在句与时间介词" tabindex="-1">Lesson 69 · 过去存在句与时间介词 <a class="header-anchor" href="#lesson-69-·-过去存在句与时间介词" aria-label="Permalink to &quot;Lesson 69 · 过去存在句与时间介词 {#lesson-69-·-过去存在句与时间介词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> There were hundreds of people at the race.</p><h3 id="练习-1-20" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-20" aria-label="Permalink to &quot;练习 1 {#练习-1-20}&quot;">​</a></h3><p>填 be 过去式：There ___ hundreds of people.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> were</p><p><strong>解析：</strong> 按本课规则判断：there was/there were 介绍过去存在的事物，be 的数取决于后面的名词。There were many people 强调过去人多。on 用具体某天或日期，in 用月份年份等，at 用钟点；含 last、next、every 的时间短语通常不再加介词，如 last Sunday。when 询问时间，不等于 where。</p></details><p><strong>表达迁移：</strong> 围绕“描述过去一场活动的时间与场景”写两至三句，再读给同伴听。至少使用一次过去存在句与时间介词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>There were hundreds of people at the race. The final was on Sunday afternoon.</p><p>There were 引出过去存在的人群；hundreds of people 是复数，at the race 表现场。 The final 是单数主语，用 was；on Sunday afternoon 是具体某天下午，所以使用 on。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-069">回看本课</a></p>',60)])])}const m=t(n,[["render",r]]);export{c as __pageData,m as default};
